# ===== ch9: 定时器/计数器 =====
s("9", "MCS-51有几个定时器/计数器？", ["2个", "1个", "3个", "4个"], "A", "MCS-51有T0和T1两个16位定时器/计数器。")
s("9", "定时器模式1是几位定时器？", ["16位", "13位", "8位自动重装", "8位"], "A", "模式1为16位定时器(TH+TL)，模式0为13位，模式2为8位自动重装。")
s("9", "MCS-51中 TMOD 寄存器的作用是？", ["设置定时器工作模式", "启动定时器", "设置波特率", "设置中断优先级"], "A", "TMOD控制T0和T1的工作方式(C/T选择、M1/M0模式、GATE门控)。")
s("9", "TMOD中GATE=1时定时器启动需要？", ["TRx=1且INTx高电平", "仅TRx=1", "仅INTx高电平", "EA=1"], "A", "GATE=1时需TRx置1且外部中断引脚INTx为高电平才启动，用于脉冲宽度测量。")
s("9", "12MHz晶振下，定时器模式1最大定时时间是？", ["65.536ms", "8.192ms", "256us", "1ms"], "A", "模式1为16位，最大计数值65536，12MHz/12=1MHz，65536/1MHz=65.536ms。")
s("9", "TMOD中C/T=1时定时器工作在？", ["计数器模式", "定时器模式", "串口模式", "中断模式"], "A", "C/T=0为定时器(内部时钟)，C/T=1为计数器(外部脉冲)。")
s("9", "定时器模式2(8位自动重装)常用于？", ["波特率发生", "长延时", "PWM输出", "频率计"], "A", "模式2自动重装特性适合做串口波特率发生器。")
s("9", "12MHz晶振下，定时器模式2定时256us，初值为？", ["0x00", "0xFF", "0x80", "0x56"], "A", "模式2定时256us需计256个数，初值=256-256=0x00。")
s("9", "定时器0的启动控制位是？", ["TR0", "TF0", "ET0", "PT0"], "A", "TCON中TR0控制T0启停，TF0是溢出标志，ET0是中断允许，PT0是优先级。")
s("9", "定时器中断标志位TF0在何时被硬件置1？", ["定时器溢出时", "定时器启动时", "定时器停止时", "中断响应时"], "A", "T0溢出时硬件自动置TF0=1，若中断使能则触发中断，中断响应后硬件自动清零。")
m("9", "定时器/计数器的工作模式有？", ["模式0(13位)", "模式1(16位)", "模式2(8位自动重装)", "模式3(双8位)"], ["A","B","C","D"], "M0/M1组合选择4种工作模式，T1不支持模式3。")
m("9", "定时器初值计算需要已知的参数有？", ["晶振频率", "机器周期", "所需定时时间", "工作模式"], ["A","B","C","D"], "初值=最大计数值-定时时间/机器周期，需知道以上所有参数。")
m("9", "定时器模式1用于长延时的方法包括？", ["软件计数溢出次数", "中断中重装初值", "多级定时器串联", "使用_nop_()"], ["A","B","C"], "长延时需多次溢出计数，中断中重装初值，或串联定时器；_nop_()不适合长延时。")
m("9", "TMOD寄存器的位定义包括？", ["GATE", "C/T", "M1", "M0"], ["A","B","C","D"], "TMOD高低4位分别控制T1和T0，每4位含GATE、C/T、M1、M0。")
m("9", "定时器/计数器的应用场景有？", ["定时中断", "脉冲计数", "波特率发生", "PWM输出"], ["A","B","C","D"], "定时器可定时、计数外部脉冲、产生波特率、通过软件模拟PWM。")
j("9", "MCS-51定时器在模式1下溢出后需要手动重装初值。", True, "模式1无自动重装功能，溢出后需在中断中手动重写TH和TL初值。")
j("9", "定时器模式2的TL是运行寄存器，TH是重装值寄存器。", True, "模式2中TL计数溢出后，硬件自动将TH的值装入TL继续计数。")
j("9", "12MHz晶振下，机器周期为1us。", True, "12T模式下机器周期=12/12MHz=1us。")
j("9", "定时器作为计数器时，计数脉冲来自内部时钟。", False, "计数器模式下计数脉冲来自外部引脚T0(P3.4)或T1(P3.5)，非内部时钟。")
t("9", "简述MCS-51定时器的4种工作模式。", "模式0：13位定时器(TH 8位+TL低5位)，最大计8192；模式1：16位定时器(TH+TL各8位)，最大计65536，最常用；模式2：8位自动重装(TL计数，TH存重装值)，溢出后自动重装，适合波特率发生；模式3：T0拆分为两个独立8位定时器，T1停止。", "四种模式各有用途，模式1和2最常用。")
t("9", "12MHz晶振下用定时器0模式1产生10ms定时，计算初值并写出初始化代码。", "计算：机器周期=12/12MHz=1us；计数值=10ms/1us=10000；初值=65536-10000=55536=0xD8F0；TH0=0xD8，TL0=0xF0。初始化：TMOD=0x01(T0模式1定时)；TH0=0xD8; TL0=0xF0; ET0=1; EA=1; TR0=1;", "初值计算是定时器编程核心。")
t("9", "简述定时器实现PWM输出的原理。", "原理：利用定时器中断在固定周期内改变高低电平时间占空比。方法：1)设定时器周期为PWM周期(如2kHz=500us)；2)在中断中比较计数值与占空比阈值；3)计数值<阈值时输出高电平，否则输出低电平；4)改变阈值即可改变占空比。也可用定时器输出比较模式自动产生PWM。MCS-51无硬件PWM，需软件实现。", "软件PWM通过定时器中断模拟。")

# ===== ch10: 串行通信 =====
s("10", "MCS-51串口的发送缓冲器和接收缓冲器是？", ["SBUF(共用地址)", "两个独立地址", "ACC", "DPTR"], "A", "SBUF物理上是两个寄存器(发送和接收)，共用一个地址99H，由读写方向区分。")
s("10", "MCS-51串口控制寄存器是？", ["SCON", "PCON", "TCON", "TMOD"], "A", "SCON控制串口工作方式、串口中断标志(TI/RI)等。")
s("10", "串口方式1是？", ["8位UART", "9位UART", "同步移位寄存器", "8位固定波特率"], "A", "方式1为8位UART(1起始+8数据+1停止)，波特率可变，最常用。")
s("10", "MCS-51中TI标志位表示？", ["发送完成", "接收完成", "发送中", "接收中"], "A", "TI=1表示一帧数据发送完毕，需软件清零；RI=1表示接收完毕。")
s("10", "串口方式1的波特率由哪个定时器产生？", ["定时器1", "定时器0", "定时器2", "内部固定"], "A", "方式1和3的波特率由定时器1的溢出率决定。")
s("10", "12MHz晶振下，方式1波特率9600时定时器1模式2的初值为？", ["0xFD", "0xFF", "0xFA", "0xF3"], "A", "波特率=(2^SMOD/32)x(T1溢出率)，12MHz下TH1≈253=0xFD，有约8.5%误差。")
s("10", "MCS-51串口接收允许位是？", ["REN", "TI", "RI", "SM0"], "A", "SCON中REN=1允许接收，REN=0禁止接收。")
s("10", "SCON中SM0=0,SM1=1表示串口工作在？", ["方式1", "方式0", "方式2", "方式3"], "A", "SM0/SM1：00=方式0，01=方式1，10=方式2，11=方式3。")
s("10", "串口发送数据时，写入SBUF后应？", ["等待TI置1", "等待RI置1", "直接读SBUF", "关闭串口"], "A", "写SBUF启动发送，发送完成后硬件置TI=1，查询或中断方式等待TI。")
s("10", "PCON中SMOD=1的作用是？", ["波特率加倍", "波特率减半", "进入空闲模式", "进入掉电模式"], "A", "SMOD=1时波特率加倍，用于提高波特率或减少定时器误差。")
m("10", "MCS-51串口的工作方式有？", ["方式0(同步移位)", "方式1(8位UART)", "方式2(9位固定波特率)", "方式3(9位可变波特率)"], ["A","B","C","D"], "4种方式由SCON中SM0/SM1选择。")
m("10", "串口通信中常用的校验方式有？", ["奇校验", "偶校验", "无校验", "CRC校验"], ["A","B","C"], "奇偶校验和无校验最常用；CRC通常用于数据块而非单字节。")
m("10", "MCS-51串口方式1的数据帧包含？", ["1位起始位", "8位数据位", "1位停止位", "1位校验位"], ["A","B","C"], "方式1帧格式：1起始+8数据+1停止，共10位，无校验位。")
m("10", "串口通信初始化步骤包括？", ["设置SCON工作方式", "设置TMOD和T1初值", "设置中断允许", "启动T1"], ["A","B","C","D"], "初始化需设SCON、TMOD、TH1/TL1、IE、TR1。")
m("10", "串口通信中常见的问题有？", ["波特率不匹配", "电平不匹配", "TX/RX接反", "晶振频率影响"], ["A","B","C","D"], "波特率不匹配导致乱码，TTL/RS232电平不匹配需转换，TX/RX需交叉，12MHz晶振有波特率误差。")
j("10", "MCS-51的SBUF发送缓冲器和接收缓冲器物理上是同一个寄存器。", False, "SBUF物理上是两个独立寄存器，共用地址99H，由读/写操作区分访问。")
j("10", "串口方式1的波特率是固定的，不可改变。", False, "方式1波特率由定时器1溢出率决定，可变可调。")
j("10", "串口接收中断标志RI需要软件手动清零。", True, "RI不会硬件自动清除，需在中断或查询处理中手动清零。")
j("10", "使用11.0592MHz晶振可以获得更精确的标准波特率。", True, "11.0592MHz能被标准波特率整除，误差为0，常用于串口通信。")
t("10", "简述MCS-51串口4种工作方式的特点和用途。", "方式0：同步移位寄存器，8位数据，波特率固定为fosc/12，用于扩展I/O；方式1：8位UART，波特率可变(T1)，最常用的异步通信方式；方式2：9位UART，波特率固定为fosc/64或fosc/32，用于多机通信；方式3：9位UART，波特率可变(T1)，功能最全。常用方式1。", "四种方式各有特点，方式1最常用。")
t("10", "计算11.0592MHz晶振下方式1波特率9600时定时器1模式2的初值。", "公式：波特率=(2^SMOD/32)xfosc/(12x(256-TH1))。SMOD=0：9600=(1/32)x11059200/(12x(256-TH1))。TH1=256-11059200/(32x12x9600)=256-3=253=0xFD。验证：波特率=11059200/(384x3)=9600，误差0%。", "11.0592MHz的优势是标准波特率误差为零。")
t("10", "编写MCS-51串口方式1接收中断服务函数的C51代码框架。", "void uart_isr() interrupt 4 { if(RI) { RI=0; //手动清接收标志; recv_buf = SBUF; //读取接收数据; //处理接收数据; } if(TI) { TI=0; //手动清发送标志; //可在此处理发送完成; } }。注意：串口中断号=4，需判断RI/TI确定中断来源。", "串口中断需判断RI/TI区分收发。")

